function kernelCounts(s, eMax, cmp) {
  const out = [];
  const seen = new Set();
  for (let e = 0; e <= eMax; e++) {
    for (let r = 0; r < (1 << e); r++) {
      const need = r + ((cmp - 1) << e);
      if (need >= s.length) return out.concat(Array(eMax - e + 1).fill(null));
      let key = '';
      for (let n = 0; n < cmp; n++) key += String(s[r + (n << e)]) + ',';
      seen.add(key);
    }
    out.push(seen.size);
  }
  return out;
}

